const fs = require("fs");
const path = require("path");

function findBase() {
  if (fs.existsSync("frontend/src/pages/QuizHub.jsx")) return "frontend";
  if (fs.existsSync("src/pages/QuizHub.jsx")) return ".";
  console.error("❌ Hindi makita ang frontend/ folder. I-run ito sa project root (yung may frontend/ folder).");
  process.exit(1);
}
const base = findBase();

function patchAnchor(relPath, edits) {
  const filePath = path.join(base, relPath);
  let content = fs.readFileSync(filePath, "utf8");
  let changed = false;
  for (const [oldStr, newStr] of edits) {
    if (content.includes(newStr)) continue; // already applied
    const count = content.split(oldStr).length - 1;
    if (count !== 1) {
      console.error('❌ ' + relPath + ': inaasahang 1 match, nakita ' + count + '. Walang binago dito. Anchor: ' + oldStr.slice(0, 70));
      process.exit(1);
    }
    content = content.split(oldStr).join(newStr);
    changed = true;
  }
  if (changed) {
    fs.writeFileSync(filePath + ".bak", fs.readFileSync(filePath));
    fs.writeFileSync(filePath, content);
    console.log("✅ Na-patch: " + relPath + "  (backup: " + relPath + ".bak)");
  } else {
    console.log("ℹ️ Na-apply na dati: " + relPath);
  }
}

function patchWholeFile(relPath, expectedOld, newContent) {
  const filePath = path.join(base, relPath);
  const current = fs.readFileSync(filePath, "utf8");
  if (current === newContent) {
    console.log("ℹ️ Na-apply na dati: " + relPath);
    return;
  }
  if (current !== expectedOld) {
    console.error("❌ " + relPath + ": hindi tugma sa inaasahan ng patch (baka may ibang changes na). Walang binago.");
    process.exit(1);
  }
  fs.writeFileSync(filePath + ".bak", current);
  fs.writeFileSync(filePath, newContent);
  console.log("✅ Na-patch: " + relPath + "  (backup: " + relPath + ".bak)");
}

